CREATE DATABASE IF NOT EXISTS driveease CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE driveease;

CREATE TABLE users (user_id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,phone VARCHAR(20),role ENUM('CUSTOMER','ADMIN') NOT NULL DEFAULT 'CUSTOMER',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE driving_licenses (license_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL UNIQUE,license_number VARCHAR(60) NOT NULL UNIQUE,issue_date DATE NOT NULL,expiry_date DATE NOT NULL,license_status ENUM('VALID','EXPIRED','SUSPENDED') DEFAULT 'VALID',CONSTRAINT fk_license_user FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE,CHECK(expiry_date > issue_date));
CREATE TABLE vehicles (vehicle_id INT AUTO_INCREMENT PRIMARY KEY,vehicle_number VARCHAR(30) NOT NULL UNIQUE,brand VARCHAR(60) NOT NULL,model VARCHAR(80) NOT NULL,vehicle_type ENUM('CAR','BIKE') NOT NULL,year SMALLINT NOT NULL,fuel_type ENUM('PETROL','DIESEL','ELECTRIC','HYBRID') NOT NULL,transmission ENUM('MANUAL','AUTOMATIC') NOT NULL,price_per_day DECIMAL(10,2) NOT NULL,status ENUM('AVAILABLE','MAINTENANCE','RETIRED') NOT NULL DEFAULT 'AVAILABLE',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CHECK(price_per_day > 0));
CREATE TABLE vehicle_images (image_id INT AUTO_INCREMENT PRIMARY KEY,vehicle_id INT NOT NULL,image_url VARCHAR(500) NOT NULL,FOREIGN KEY(vehicle_id) REFERENCES vehicles(vehicle_id) ON DELETE CASCADE);
CREATE TABLE bookings (booking_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,vehicle_id INT NOT NULL,pickup_date DATE NOT NULL,dropoff_date DATE NOT NULL,booking_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,total_amount DECIMAL(10,2) NOT NULL,booking_status ENUM('PENDING','APPROVED','REJECTED','CANCELLED') DEFAULT 'PENDING',FOREIGN KEY(user_id) REFERENCES users(user_id),FOREIGN KEY(vehicle_id) REFERENCES vehicles(vehicle_id),CHECK(dropoff_date > pickup_date),CHECK(total_amount >= 0),INDEX idx_booking_lookup(vehicle_id,booking_status,pickup_date,dropoff_date));
CREATE TABLE payments (payment_id INT AUTO_INCREMENT PRIMARY KEY,booking_id INT NOT NULL UNIQUE,amount DECIMAL(10,2) NOT NULL,payment_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,payment_method ENUM('CARD','UPI','CASH') NOT NULL,payment_status ENUM('PENDING','SUCCESS','FAILED','REFUNDED') NOT NULL DEFAULT 'PENDING',transaction_reference VARCHAR(80) UNIQUE,FOREIGN KEY(booking_id) REFERENCES bookings(booking_id),CHECK(amount>=0));
CREATE TABLE maintenance (maintenance_id INT AUTO_INCREMENT PRIMARY KEY,vehicle_id INT NOT NULL,maintenance_type VARCHAR(100) NOT NULL,description TEXT,start_date DATE NOT NULL,end_date DATE,cost DECIMAL(10,2) DEFAULT 0,maintenance_status ENUM('SCHEDULED','IN_PROGRESS','COMPLETED') DEFAULT 'SCHEDULED',FOREIGN KEY(vehicle_id) REFERENCES vehicles(vehicle_id),CHECK(end_date IS NULL OR end_date>=start_date),INDEX idx_maintenance_lookup(vehicle_id,maintenance_status,start_date));
CREATE TABLE trip_details (trip_id INT AUTO_INCREMENT PRIMARY KEY,booking_id INT NOT NULL UNIQUE,destination VARCHAR(160) NOT NULL,distance_km DECIMAL(8,2),estimated_fuel_cost DECIMAL(10,2) DEFAULT 0,estimated_trip_cost DECIMAL(10,2) DEFAULT 0,FOREIGN KEY(booking_id) REFERENCES bookings(booking_id) ON DELETE CASCADE);
CREATE TABLE reviews (review_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,vehicle_id INT NOT NULL,rating TINYINT NOT NULL,comment TEXT,review_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(user_id),FOREIGN KEY(vehicle_id) REFERENCES vehicles(vehicle_id),UNIQUE(user_id,vehicle_id),CHECK(rating BETWEEN 1 AND 5));

CREATE OR REPLACE VIEW booking_details AS SELECT b.booking_id,b.user_id,u.name customer_name,u.email,v.brand,v.model,v.vehicle_number,b.pickup_date,b.dropoff_date,b.total_amount,b.booking_status,p.payment_status FROM bookings b JOIN users u ON u.user_id=b.user_id JOIN vehicles v ON v.vehicle_id=b.vehicle_id LEFT JOIN payments p ON p.booking_id=b.booking_id;
CREATE OR REPLACE VIEW vehicle_utilization AS SELECT v.vehicle_id,CONCAT(v.brand,' ',v.model) vehicle,v.vehicle_type,COUNT(b.booking_id) booking_count,COALESCE(SUM(CASE WHEN b.booking_status='APPROVED' THEN DATEDIFF(b.dropoff_date,b.pickup_date) ELSE 0 END),0) rented_days FROM vehicles v LEFT JOIN bookings b ON b.vehicle_id=v.vehicle_id GROUP BY v.vehicle_id;
DELIMITER //
CREATE TRIGGER maintenance_after_insert AFTER INSERT ON maintenance FOR EACH ROW BEGIN IF NEW.maintenance_status IN ('SCHEDULED','IN_PROGRESS') THEN UPDATE vehicles SET status='MAINTENANCE' WHERE vehicle_id=NEW.vehicle_id; END IF; END//
CREATE TRIGGER maintenance_after_update AFTER UPDATE ON maintenance FOR EACH ROW BEGIN IF NEW.maintenance_status='COMPLETED' AND NOT EXISTS(SELECT 1 FROM maintenance WHERE vehicle_id=NEW.vehicle_id AND maintenance_status IN ('SCHEDULED','IN_PROGRESS')) THEN UPDATE vehicles SET status='AVAILABLE' WHERE vehicle_id=NEW.vehicle_id; END IF; END//
CREATE PROCEDURE customer_booking_history(IN input_user_id INT) SELECT * FROM booking_details WHERE user_id=input_user_id ORDER BY pickup_date DESC//
DELIMITER ;
